-- 0001_foundation
-- Cross-cutting tables needed before any feature exists.
-- Conventions for every migration:
--   * Timestamps are ISO-8601 UTC text with milliseconds (strftime('%Y-%m-%dT%H:%M:%fZ','now')).
--   * Primary keys are UUID text generated by the application.
--   * Coordinates, when stored, are separate REAL lat/lng columns (never packed strings) so they can
--     be indexed now and moved to PostGIS geometry columns later.
--   * JSON columns are named *_json and constrained with json_valid().

-- Append-only record of security-sensitive actions (logins, SOS changes, moderation, permission
-- changes). Deliberately has no foreign keys so the trail survives deletion of the subject.
-- Sensitivity: RESTRICTED. Readable by administrators only. Must not contain precise coordinates,
-- phone numbers or message bodies; metadata holds identifiers and coarse context only.
CREATE TABLE audit_events (
  id             TEXT PRIMARY KEY,
  occurred_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  actor_type     TEXT NOT NULL CHECK (actor_type IN ('user', 'system', 'admin', 'moderator')),
  actor_id       TEXT,
  action         TEXT NOT NULL CHECK (length(action) BETWEEN 3 AND 100),
  target_type    TEXT,
  target_id      TEXT,
  request_id     TEXT,
  metadata_json  TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(metadata_json))
);

CREATE INDEX idx_audit_events_actor  ON audit_events (actor_id, occurred_at);
CREATE INDEX idx_audit_events_target ON audit_events (target_type, target_id, occurred_at);
CREATE INDEX idx_audit_events_action ON audit_events (action, occurred_at);

-- Audit rows are append-only.
CREATE TRIGGER audit_events_no_update BEFORE UPDATE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit_events is append-only');
END;
